SELECT

FROM couple_anniversary
WHERE couple_id = #{coupleId,jdbcType=BIGINT}
AND deleted = 0
AND (

    (
        DATE_FORMAT(CONCAT(YEAR(#{currentDate,jdbcType=DATE}), '-', MONTH(anniversary_date), '-', DAY(anniversary_date)), '%Y-%m-%d') >= #{currentDate,jdbcType=DATE}
        AND DATEDIFF(
            DATE_FORMAT(CONCAT(YEAR(#{currentDate,jdbcType=DATE}), '-', MONTH(anniversary_date), '-', DAY(anniversary_date)), '%Y-%m-%d'),
            #{currentDate,jdbcType=DATE}
        ) <= remind_days
    )
    OR

    (
        DATE_FORMAT(CONCAT(YEAR(#{currentDate,jdbcType=DATE}), '-', MONTH(anniversary_date), '-', DAY(anniversary_date)), '%Y-%m-%d') < #{currentDate,jdbcType=DATE}
        AND DATEDIFF(
            DATE_FORMAT(CONCAT(YEAR(#{currentDate,jdbcType=DATE}) + 1, '-', MONTH(anniversary_date), '-', DAY(anniversary_date)), '%Y-%m-%d'),
            #{currentDate,jdbcType=DATE}
        ) <= remind_days
    )
)
ORDER BY anniversary_date ASC

SELECT

FROM couple_anniversary
WHERE id = #{anniversaryId,jdbcType=BIGINT}
AND couple_id = #{coupleId,jdbcType=BIGINT}
AND deleted = 0

SELECT

FROM couple_anniversary
WHERE couple_id = #{coupleId,jdbcType=BIGINT}
AND anniversary_type = #{anniversaryType,jdbcType=TINYINT}
AND deleted = 0
LIMIT 1

SELECT

FROM couple_anniversary
WHERE couple_id = #{coupleId,jdbcType=BIGINT}
AND anniversary_date = #{anniversaryDate,jdbcType=DATE}
AND deleted = 0
ORDER BY anniversary_type ASC
